/**
 * Jinx Lleech + Mastermind: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lleech
 * Wiki: https://wiki.bloodontheclocktower.com/Mastermind
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/abilities/ability.ts';
import { gameEnds } from '#lib/core/rules/game-end/game-end.ts';
import { aliveForEnd } from '#lib/core/rules/game-end/game-end-helpers.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { survivesCarrierBy } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Lleech + Mastermind jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lleech', 'mastermind');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lleech')?.name).toBe('Lleech');
		expect(data.byId.get('mastermind')?.name).toBe('Mastermind');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lleech', 'mastermind'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lleech'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['mastermind'])).not.toContain(jinx);
	});

	describe('with the Mastermind alive, an executed host leaves the Lleech alive with no ability', () => {
		const ids = ['lleech', 'mastermind', 'chef', 'empath', 'monk', 'soldier'];
		// The Lleech's host is the Chef.
		const base = scenario(ids, { script: scriptOf(ids) }).reminder('chef', 'lleech', 'Poisoned');
		const lleech = (s: Scenario) => ({
			alive: aliveForEnd(s.game, s.seat('lleech'), s.characters),
			reasons: abilityState(s.game, s.seat('lleech'), s.characters).impairments.map((i) => i.reason)
		});
		const goodWins = (s: Scenario) =>
			gameEnds(s.game, s.characters).some((e) => e.rule === 'demon-dead');

		it("is data in the Lleech's rules", () => {
			// Wiki: "If the Mastermind is alive and the Lleech host dies by execution, the Lleech lives but loses their ability."
			expect(ownJinxRules(base.game, 'lleech', 'mastermind', base.characters)).toEqual({
				survives: { on: 'carrier-executed', when: ['partner-alive'] }
			});
		});

		it('keeps the Lleech alive, with no ability, when its host is executed', () => {
			// Wiki: "the Lleech lives but loses their ability."
			const s = base.execute('chef');
			expect(survivesCarrierBy(s.game, s.seat('lleech'), s.characters)).toBe('mastermind');
			expect(lleech(s)).toEqual({ alive: true, reasons: ['no-ability'] });
			expect(goodWins(s)).toBe(false);
		});

		it('lets the Lleech die with a host killed some other way', () => {
			// Wiki: "the Lleech host dies by execution"
			const s = base.dies('chef', 'lleech');
			expect(survivesCarrierBy(s.game, s.seat('lleech'), s.characters)).toBeUndefined();
			expect(lleech(s).alive).toBe(false);
		});

		it('lets the Lleech die with its executed host once the Mastermind is dead', () => {
			// Wiki: "If the Mastermind is alive"
			const s = base.dies('mastermind').execute('chef');
			expect(lleech(s).alive).toBe(false);
			expect(goodWins(s)).toBe(true);
		});
	});
});
